// Aplati les resultats Apify et attache le compte cible
const items = $input.all();
const out = [];
for (const item of items) {
  const profiles = Array.isArray(item.json) ? item.json : [item.json];
  for (const p of profiles) {
    if (!p || !p.linkedinUrl) continue;
    out.push({ json: { ...p, targetAccountName: 'Jean-Pierre Martin', targetAccountId: 'yTr-07HvRiuQacAP3ZCiOQ' } });
  }
}
return out;

// Scoring ICP sur 100 pts (grille validee) — ne garde que score >= 60
function parseDurationMonths(duration) {
  if (!duration) return 0;
  let months = 0;
  const yrMatch = duration.match(/(\d+)\s*yr/);
  const moMatch = duration.match(/(\d+)\s*mo/);
  if (yrMatch) months += parseInt(yrMatch[1], 10) * 12;
  if (moMatch) months += parseInt(moMatch[1], 10);
  return months;
}

function scoreProfile(p) {
  const pos = (p.currentPosition && p.currentPosition[0]) || {};
  const headline = (p.headline || p.summary || '').toLowerCase();
  const posTitle = (pos.position || '').toLowerCase();
  const desc = (pos.description || '').toLowerCase();
  const months = parseDurationMonths(pos.duration);

  let s1 = 0;
  const isFounder = /fondateur|founder|ceo|dirigeant|president|associe|co-fondateur|co-founder/.test(posTitle) || /fondateur|founder|ceo|dirigeant/.test(headline);
  if (isFounder) s1 += 15;
  if (months >= 12) s1 += 15;
  else if (months >= 6) s1 += 7;

  let s2 = 0;
  const iaKeywords = /intelligence artificielle|\bia\b|automatisation|agents ia|ai\b/;
  const b2bKeywords = /entreprise|b2b|pme|eti|agence|cabinet|consultant/;
  if (iaKeywords.test(headline) || iaKeywords.test(desc)) s2 += 15;
  if (b2bKeywords.test(headline) || b2bKeywords.test(desc)) s2 += 10;

  let s3 = 0;
  if (/recrute|recrutement|hiring|nous cherchons/.test(desc)) s3 += 10;
  if (/client|resultat|generated|accompagn|partenaire|partnership/.test(desc)) s3 += 10;
  if (p.followerCount && p.followerCount > 1000) s3 += 5;

  let s4 = 0;
  if (/equipe|team|collaborateur|associe|co-fondateur|co-founder/.test(desc) || /co-fondateur|co-founder/.test(posTitle)) s4 += 20;
  else if (pos.employmentType === 'Self-employed' || pos.employmentType === 'Freelance') s4 += 5;

  const total = s1 + s2 + s3 + s4;
  return { total, s1, s2, s3, s4, months, isFounder };
}

const items = $input.all();
const out = [];
for (const item of items) {
  const p = item.json;
  const score = scoreProfile(p);
  if (score.total < 60) continue;
  const pos = (p.currentPosition && p.currentPosition[0]) || {};
  out.push({
    json: {
      id: p.id,
      name: (p.firstName || '') + ' ' + (p.lastName || ''),
      linkedinUrl: p.linkedinUrl,
      publicIdentifier: (p.linkedinUrl || '').match(/linkedin\.com\/in\/([^/?]+)/)?.[1] || '',
      headline: p.headline || p.summary || '',
      company: pos.companyName || '',
      companyLinkedinUrl: pos.companyLinkedinUrl || '',
      score: score.total,
      targetAccountName: p.targetAccountName,
      targetAccountId: p.targetAccountId
    }
  });
}
return out;

const key = "<UNIPILE_API_KEY>";
const base = "https://api43.unipile.com:17313";
const results = [];

for (const item of $input.all()) {
  const p = item.json;
  let employeeCount = null;
  const companyPublicId = (p.companyLinkedinUrl || '').match(/linkedin\.com\/company\/([^/?]+)/)?.[1] || '';

  if (companyPublicId) {
    try {
      const resp = await this.helpers.httpRequest({
        method: 'GET',
        url: base + '/api/v1/linkedin/company/' + companyPublicId + '?account_id=' + p.targetAccountId,
        headers: { 'X-API-KEY': key },
        json: true
      });
      employeeCount = resp.employee_count != null ? resp.employee_count : null;
    } catch (e) {
      employeeCount = null;
    }
  }

  // Critere obligatoire: entre 2 et 10 personnes dans l'entreprise (sweet spot pour l'offre 2000e/mois
  // - en dessous de 2, budget hors de portee ; au dessus de 10, plus le meme profil de decideur/besoin)
  if (employeeCount === null || employeeCount < 2 || employeeCount > 10) continue;

  // Bonus de score pour effectif dans la fourchette ideale
  let effectifBonus = 0;
  if (employeeCount >= 5) effectifBonus = 15;
  else if (employeeCount >= 2) effectifBonus = 10;

  results.push({ json: { ...p, employeeCount, score: (p.score || 0) + effectifBonus } });
}

return results;

const key = "<UNIPILE_API_KEY>";
const base = "https://api43.unipile.com:17313";

let sentIds = new Set();
try {
  const resp = await this.helpers.httpRequest({
    method: 'GET',
    url: base + '/api/v1/users/invite/sent?account_id=DKq0OfZ5SLikHnt5BVEj2w&limit=200',
    headers: { 'X-API-KEY': key },
    json: true,
  });
  (resp.items || []).forEach(i => { if (i.invited_user_id) sentIds.add(i.invited_user_id); });
} catch (e) {}

const staticData = $getWorkflowStaticData('global');
staticData.triedIds = staticData.triedIds || {};
const now = Date.now();
const TWELVE_HOURS = 12 * 3600000;
for (const id of Object.keys(staticData.triedIds)) {
  if (now - staticData.triedIds[id] > TWELVE_HOURS) delete staticData.triedIds[id];
}
const triedRecently = new Set(Object.keys(staticData.triedIds));

const items = $input.all();
const fresh = items.filter(i => !sentIds.has(i.json.id) && !triedRecently.has(i.json.id));
fresh.sort((a, b) => (b.json.score || 0) - (a.json.score || 0));
const picked = fresh.slice(0, 16);

// Pre-calcule un instant d'envoi cible pour chacun, reparti uniformement entre maintenant et 19h00 Paris,
// avec un jitter +/-20% pour eviter un pattern parfaitement regulier.
const parisNow = new Date(new Date().toLocaleString('en-US', { timeZone: 'Europe/Paris' }));
const endOfWindow = new Date(parisNow);
endOfWindow.setHours(19, 0, 0, 0);
const msRemaining = Math.max(endOfWindow.getTime() - parisNow.getTime(), 0);
const n = Math.max(picked.length, 1);
const baseIntervalMs = msRemaining / n;

let cursorMs = 0;
for (let idx = 0; idx < picked.length; idx++) {
  const jitterFactor = 0.8 + Math.random() * 0.4;
  cursorMs += baseIntervalMs * jitterFactor;
  picked[idx].json._waitSeconds = Math.min(Math.max(Math.round(cursorMs / 1000), 20), 39600);
}
// _waitSeconds est un delai CUMULE depuis le debut du run (pas un delai relatif au lead precedent),
// donc chaque etape Wait doit soustraire le temps deja ecoule pour rester alignee sur la fenetre.
if (picked.length) picked[0].json._runStartMs = Date.now();
for (let idx = 1; idx < picked.length; idx++) picked[idx].json._runStartMs = picked[0].json._runStartMs;

return picked;

const parisHour = parseInt(new Intl.DateTimeFormat('fr-FR', { timeZone: 'Europe/Paris', hour: 'numeric', hour12: false }).format(new Date()), 10);
if (parisHour < 8 || parisHour >= 19) {
  return [];
}
return [{ json: $input.item.json }];

const key = "<UNIPILE_API_KEY>";
const base = "https://api43.unipile.com:17313";
const lead = $input.item.json;
const providerId = $json.id;
const accountId = 'yTr-07HvRiuQacAP3ZCiOQ';

// Codes typiques de quota/rate-limit LinkedIn releves par Unipile : 422 (cannot_resend_yet),
// 429 (rate limit), 500 (erreur generique cote LinkedIn). On retente 2 fois avec backoff court
// avant d'abandonner ce lead et de laisser le workflow continuer sur le suivant.
const RETRYABLE_STATUS = [422, 429, 500];
const MAX_ATTEMPTS = 3;

let lastError = null;
let sent = false;

for (let attempt = 1; attempt <= MAX_ATTEMPTS && !sent; attempt++) {
  try {
    await this.helpers.httpRequest({
      method: 'POST',
      url: base + '/api/v1/users/invite',
      headers: { 'X-API-KEY': key, 'Content-Type': 'application/json' },
      body: { provider_id: providerId, account_id: accountId },
      json: true,
    });
    sent = true;
  } catch (e) {
    lastError = e;
    const status = e.response?.statusCode || e.statusCode || e.status || 0;
    const quotaLikely = RETRYABLE_STATUS.includes(status);
    if (!quotaLikely || attempt === MAX_ATTEMPTS) break;
    const backoffMs = attempt === 1 ? 15000 : 45000;
    await new Promise(r => setTimeout(r, backoffMs));
  }
}

return [{
  json: {
    ...lead,
    _inviteSent: sent,
    _inviteSkippedReason: sent ? null : ('quota_or_error_status_' + (lastError?.response?.statusCode || lastError?.statusCode || 'unknown')),
  }
}];

const staticData = $getWorkflowStaticData('global');
staticData.triedIds = staticData.triedIds || {};
const lead = $('Boucle 1 lead a la fois').item.json;
if (lead && lead.id) {
  staticData.triedIds[lead.id] = Date.now();
}
return [{ json: $input.item.json }];

